#!/usr/bin/env python3
# luxarch:no-ai-attribution hook v4 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny commits / PRs carrying AI attribution.

House rule (CLAUDE.md, persistent): no `Co-Authored-By: Claude`, no "Generated with Claude
Code" in any commit or PR. The harness nudges for it, so this makes the rule mechanical.
A human Co-Authored-By trailer (not Claude/Anthropic) is fine and passes through.

PreToolUse(Bash): deny a git commit, tag or note / gh pr create|edit whose text carries AI
attribution, however git is spelled (`git -C . commit`, `git $'commit'`) and wherever the shell
runs it from. A tool call whose event cannot be read is denied.
"""

from __future__ import annotations

import os
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from _cmdtext import (
    command_text,
    executable_texts,
    git_calls,
    guarded,
    load_event,
    simple_commands,
    text_field,
    tool_input,
)

AUTHORING = re.compile(r"\bgit\s+commit\b|\bgh\s+pr\s+(?:create|edit)\b", re.IGNORECASE)
ATTRIB = re.compile(
    r"(?i)co-authored-by[:=]\s*[^\n]{0,400}(?:claude|anthropic|noreply@anthropic)"
    r"|generated\s+with\s+\[?claude"
    r"|\U0001F916\s*generated"
)


def _gh_pr_writes(argv: tuple[str, ...]) -> bool:
    words = [w for w in argv[1:] if not w.startswith("-")]
    writes = words[1:2] in (["create"], ["edit"])
    return os.path.basename(argv[0]) == "gh" and words[:1] == ["pr"] and writes


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    # TWO questions, two texts — the split `_cmdtext.segments` documents.
    #
    # "Is an authoring command actually being RUN?" is about the executable command, so it is asked
    # of MASKED text. It used to be asked of the raw string, and the scope claim this comment
    # carried ("prose about attribution elsewhere cannot trip it") was therefore false: any heredoc
    # whose BODY mentioned the authoring verb satisfied the scope test, so writing a test file or a
    # doc that quoted both an attribution trailer and that verb was denied. Found by dogfooding —
    # this hook blocked the very commit adding the regression test for its neighbour, the same
    # over-fire class `no-identity-override` hit one hook over.
    #
    # "Does the payload carry attribution?" is about what the command CARRIES, so it stays RAW —
    # the message IS the quoted payload, and masking it would blind this hook entirely.
    cmd = text_field(tool_input(ev), "command")
    authoring = (
        any(AUTHORING.search(command_text(t)) for t in executable_texts(cmd))
        or any(g.sub in ("commit", "tag", "notes") for g in git_calls(cmd))
        or any(_gh_pr_writes(sc.argv) for sc in simple_commands(cmd))
    )
    # The payload as git receives it, too: quoting removed and `$'\x61'` decoded, so a trailer
    # spelled across quotes (`"Cla"'ude'`) or in escapes reads as written.
    carried = "\n".join(" ".join(sc.argv) for sc in simple_commands(cmd))
    if not authoring or not (ATTRIB.search(cmd) or ATTRIB.search(carried)):
        return 0
    print(
        "DENIED: no AI attribution in commits or PRs.\n"
        "Remove the Co-Authored-By / 'Generated with Claude Code' line and commit again. "
        "(A human co-author trailer is fine.)",
        file=sys.stderr,
    )
    return 2


sys.exit(guarded(main, "no-ai-attribution"))
